function ArmoryLive({ items, onNotify, onAddItem }) {
  const totalStock = items.reduce((sum, item) => sum + Number(item.quantity || 0), 0)
  const minimumStock = items.reduce((sum, item) => sum + Number(item.minimumQuantity || 0), 0)
  const healthy = items.length ? Math.round(items.reduce((sum, item) => sum + item.percentage, 0) / items.length) : 0
  const lowStock = items.filter((item) => item.tone === 'low').length
  return <div className="page"><PageIntro eyebrow="Guild inventory" title="Armory" description="The item catalog is stored in Supabase. Items belong to the guild chest; member issue chests are managed from Members." action="Add item" onAction={onAddItem} /><div className="armory-overview"><div className="panel inventory-total"><span className="eyebrow">Catalog items</span><strong>{items.length}</strong><p>{totalStock} units tracked</p></div><div className="panel inventory-total"><span className="eyebrow">Needs restock</span><strong className="ember-text">{String(lowStock).padStart(2, '0')}</strong><p>{minimumStock} minimum units recorded</p></div><div className="panel inventory-total"><span className="eyebrow">Stock health</span><strong className="time-value">{healthy}%</strong><p>Calculated from saved quantities</p></div></div><section className="panel inventory-table"><div className="table-header"><span>Item</span><span>Category</span><span>Stock</span><span>Health</span><span /></div>{items.map(({ id, name, category, stock, percentage, tone }) => <div className="inventory-row" key={id || name}><div className="item-cell"><div className={`item-icon item-${tone}`}><Icon name={category === 'Weapon' ? 'swords' : 'box'} size={16} /></div><strong>{name}</strong></div><span>{category}</span><span>{stock}</span><div className="health-cell"><div className="mini-bar"><i className={`bar-${tone}`} style={{ width: `${percentage}%` }} /></div><span>{percentage}%</span></div><button className="more-button" onClick={() => onNotify(`${name} details opened`)} aria-label={`Open ${name}`}><Icon name="more" size={16} /></button></div>)}{!items.length && <EmptyState text="No items are saved yet. Add the first catalog item." />}</section></div>
}

