function Settings({ onNotify }) { const [adminEmail, setAdminEmail] = useState(''); const [pendingInvites, setPendingInvites] = useState(['pending-admin@example.com']); const inviteAdmin = () => { const email = adminEmail.trim().toLowerCase(); if (!email.endsWith('@gmail.com')) { onNotify('Use a Gmail address for admin invites'); return } setPendingInvites((current) => [...current, email]); setAdminEmail(''); onNotify(`Invite sent to ${email}`) }; return <div className="page"><PageIntro eyebrow="Guild configuration" title="Settings" description="Control how your guild uses Albion Regear." /><section className="settings-grid"><div className="panel settings-nav"><button className="settings-link active">Guild profile</button><button className="settings-link">Regear defaults</button><button className="settings-link">Admin access</button><button className="settings-link">Notifications</button></div><div className="settings-stack"><div className="panel settings-form"><div className="form-section"><span className="eyebrow">Guild profile</span><h2>Make it yours</h2><p>This is how the operations room identifies your guild.</p><label>Guild name<input defaultValue="Coup De Grace" /></label><label>Server region<select defaultValue="Americas"><option>Americas</option><option>Europe</option><option>Asia</option></select></label><button className="button button-primary" onClick={() => onNotify('Guild profile saved')}>Save changes</button></div></div><div className="panel admin-access"><div className="admin-access-heading"><div><span className="eyebrow">Closed admin network</span><h2>Invite administrators</h2><p>Members never create accounts. Only an existing admin can invite a Gmail address.</p></div><span className="access-pill"><span />Invite only</span></div><div className="access-rule"><div><span>Bootstrap admin</span><strong>Configured during Supabase setup</strong></div><span className="status status-green">Owner</span></div><div className="invite-form"><label>Admin Gmail<input value={adminEmail} onChange={(e) => setAdminEmail(e.target.value)} placeholder="you@example.com" /></label><button className="button button-primary" disabled={!adminEmail.trim()} onClick={inviteAdmin}><Icon name="plus" size={15} />Send invite</button></div><div className="pending-heading"><span>Pending invitations</span><small>{pendingInvites.length}</small></div><div className="pending-list">{pendingInvites.map((email) => <div className="pending-row" key={email}><span className="pending-avatar">@</span><strong>{email}</strong><span className="status status-ember">Awaiting signup</span></div>)}</div></div></div></section></div> }

function AdminSettings({ onNotify, session, guild }) {
  const [section, setSection] = useState('Guild profile')
  const [adminEmail, setAdminEmail] = useState('')
  const [inviteBusy, setInviteBusy] = useState(false)
  const [invites, setInvites] = useState([])
  const [inviteError, setInviteError] = useState('')
  const sections = ['Guild profile', 'Regear defaults', 'Admin access', 'Notifications']
  const refreshInvites = async () => {
    if (!guild?.id) return
    try { setInvites(await listAdminInvites(guild.id, session?.access_token)); setInviteError('') } catch (error) { setInviteError(error.message || 'Could not load invitations.') }
  }
  useEffect(() => { if (section === 'Admin access') refreshInvites() }, [guild?.id, section])
  const sendInvite = async () => {
    const email = adminEmail.trim().toLowerCase()
    if (!email) return
    setInviteBusy(true)
    setInviteError('')
    try {
      const response = await fetch('/api/invite-admin', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session?.access_token || ''}` }, body: JSON.stringify({ email }) })
      const result = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(result.error || 'Could not send the invitation.')
      setAdminEmail('')
      await refreshInvites()
      onNotify(result.message || `Invitation sent to ${email}.`)
    } catch (error) { setInviteError(error.message || 'Could not send the invitation.'); onNotify(error.message || 'Could not send the invitation.') } finally { setInviteBusy(false) }
  }
  const cancelInvite = async (invite) => {
    if (!window.confirm(`Cancel the invitation for ${invite.email}?`)) return
    try {
      const response = await fetch('/api/cancel-admin-invite', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session?.access_token || ''}` }, body: JSON.stringify({ inviteId: invite.id }) })
      const result = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(result.error || 'Could not cancel the invitation.')
      setInvites((current) => current.filter((entry) => entry.id !== invite.id))
      onNotify(result.message || 'Invitation canceled.')
    } catch (error) { onNotify(error.message || 'Could not cancel the invitation.') }
  }
  return <div className="page"><PageIntro eyebrow="Guild configuration" title="Settings" description="Keep the guild profile and access rules easy to find." /><section className="settings-grid"><div className="panel settings-nav">{sections.map((item) => <button type="button" className={`settings-link ${section === item ? 'active' : ''}`} key={item} onClick={() => setSection(item)}>{item}</button>)}</div><div className="settings-stack">{section === 'Guild profile' && <div className="panel settings-form"><div className="form-section"><span className="eyebrow">Guild profile</span><h2>Make it yours</h2><p>This is how the operations room identifies your guild.</p><label>Guild name<input defaultValue="Coup De Grace" /></label><label>Server region<select defaultValue="Asia"><option>Americas</option><option>Europe</option><option>Asia</option></select></label><button className="button button-primary" onClick={() => onNotify('Guild profile saved')}>Save changes</button></div></div>}{section === 'Regear defaults' && <div className="panel settings-form settings-info"><span className="eyebrow">Regear defaults</span><h2>Keep requests consistent</h2><p>Member default roles and issue chests are managed from Members. Death roles and replacement items are selected for each report.</p><div className="settings-info-row"><span>Available roles</span><strong>Tank · Support · Healer · DPS · Bomb · Caller</strong></div></div>}{section === 'Admin access' && <AdminInvitePanel invites={invites} inviteError={inviteError} adminEmail={adminEmail} setAdminEmail={setAdminEmail} inviteBusy={inviteBusy} onSend={sendInvite} onCancel={cancelInvite} />}{section === 'Notifications' && <div className="panel settings-form settings-info"><span className="eyebrow">Notifications</span><h2>Choose what needs attention</h2><label className="setting-check"><input type="checkbox" defaultChecked /> Open regear reminders</label><label className="setting-check"><input type="checkbox" defaultChecked /> Low armory stock warnings</label><button className="button button-primary" onClick={() => onNotify('Notification preferences saved')}>Save preferences</button></div>}</div></section></div>
}

function AdminInvitePanel({ invites, inviteError, adminEmail, setAdminEmail, inviteBusy, onSend, onCancel }) {
  const [tab, setTab] = useState('pending')
  const successful = invites.filter((invite) => invite.status === 'accepted' || invite.accepted_at)
  const pending = invites.filter((invite) => !invite.status || invite.status === 'pending' || invite.status === 'expired')
  const visible = tab === 'successful' ? successful : pending
  return <div className="panel settings-form settings-info"><span className="eyebrow">Closed admin network</span><h2>Invite an administrator</h2><p>Enter their email. Supabase sends an account setup link so they can create a password and sign in.</p><label>Admin email<input type="email" value={adminEmail} onChange={(event) => setAdminEmail(event.target.value)} placeholder="admin@gmail.com" /></label><button type="button" className="button button-primary" disabled={!adminEmail.trim() || inviteBusy} onClick={onSend}><Icon name="plus" size={15} />{inviteBusy ? 'Sending...' : 'Send invitation'}</button><small className="field-help">The invited account is linked to Coup De Grace automatically.</small><div className="invite-tabs" role="tablist"><button type="button" role="tab" aria-selected={tab === 'pending'} className={tab === 'pending' ? 'selected' : ''} onClick={() => setTab('pending')}>Pending <span>{pending.length}</span></button><button type="button" role="tab" aria-selected={tab === 'successful'} className={tab === 'successful' ? 'selected' : ''} onClick={() => setTab('successful')}>Successful <span>{successful.length}</span></button></div>{inviteError && <div className="auth-error" role="alert">{inviteError}</div>}<div className="pending-list">{visible.map((invite) => { const expired = invite.status === 'expired' || (!invite.accepted_at && invite.expires_at && new Date(invite.expires_at).getTime() < Date.now()); const accepted = invite.status === 'accepted' || invite.accepted_at; const inviter = invite.invited_by_username || invite.invited_by_email || 'Unknown admin'; return <div className="pending-row" key={invite.id}><span className="pending-avatar">@</span><div className="pending-copy"><strong>{invite.email}</strong><small>Sent {new Date(invite.created_at).toLocaleDateString()} | {accepted ? `Accepted ${new Date(invite.accepted_at).toLocaleDateString()}` : `Expires ${new Date(invite.expires_at).toLocaleDateString()}`} | Invited by {inviter}</small></div><span className={`status status-${accepted ? 'green' : expired ? 'ember' : 'blue'}`}>{accepted ? 'Successful' : expired ? 'Expired' : 'Pending'}</span>{!accepted && <button type="button" className="button button-danger invite-cancel" onClick={() => onCancel(invite)}>Cancel</button>}</div> })}{!visible.length && !inviteError && <span className="suggestion-empty">{tab === 'successful' ? 'No successful invitations yet.' : 'No pending invitations.'}</span>}</div></div>
}

