function Modal({ title, eyebrow, children, onClose }) { return <div className="modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="modal"><div className="modal-heading"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div><button className="close-button" onClick={onClose} aria-label="Close"><Icon name="close" size={19} /></button></div>{children}</div></div> }
function MemberModal({ onClose, onSave }) { const [name, setName] = useState(''); const [role, setRole] = useState('DPS'); const [chest, setChest] = useState(''); return <Modal title="Add guild member" eyebrow="Roster management" onClose={onClose}><div className="form-grid"><label>Character name<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Nightjar" /></label><label>Role<select value={role} onChange={(e) => setRole(e.target.value)}><option>Tank</option><option>Support</option><option>Healer</option><option>DPS</option><option>Bomb</option><option>Caller</option></select></label><label>Issue chest<input value={chest} onChange={(e) => setChest(e.target.value)} placeholder="e.g. C-04 or north island" /></label><label>Notes<input placeholder="Optional note" /></label></div><div className="modal-footer"><button className="button button-ghost" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={!name.trim()} onClick={() => onSave({ name: name.trim(), role, guild: 'Coup De Grace', avatar: name.trim()[0]?.toUpperCase() || '?', tone: 'teal', status: 'Open regear', chest: chest.trim() || 'Unassigned', last: 'Not yet', issuedBy: 'Pending' })}>Add member</button></div></Modal> }

function DeathModal({ members, items, onAddItem, onClose, onSave }) { const firstMember = members[0]; const [memberName, setMemberName] = useState(''); const [memberQuery, setMemberQuery] = useState(''); const [memberSuggestionsOpen, setMemberSuggestionsOpen] = useState(false); const [role, setRole] = useState(firstMember?.role || 'DPS'); const [cta, setCta] = useState('Avalonian Roads'); const [chest, setChest] = useState(''); const [selectedItems, setSelectedItems] = useState([]); const selectedMember = members.find((member) => member.name === memberName); const memberSuggestions = members.filter((member) => `${member.name} ${member.role}`.toLowerCase().includes(memberQuery.toLowerCase())).slice(0, 6); const chooseMember = (member) => { setMemberName(member.name); setMemberQuery(member.name); setRole(member.role); setChest(member.chest); setMemberSuggestionsOpen(false) }; return <Modal title="Report a CTA death" eyebrow="Create regear request" onClose={onClose}><div className="form-grid"><div className="member-search-field"><label>Member</label><div className="member-search"><Icon name="search" size={15} /><input autoFocus value={memberQuery} onFocus={() => setMemberSuggestionsOpen(true)} onChange={(e) => { setMemberQuery(e.target.value); setMemberName(''); setMemberSuggestionsOpen(true) }} placeholder="Search character name..." /></div>{memberSuggestionsOpen && memberQuery.trim() && <div className="member-suggestion-box">{memberSuggestions.map((member) => <button type="button" key={member.name} onMouseDown={(e) => e.preventDefault()} onClick={() => chooseMember(member)}><span className={`avatar avatar-${member.tone}`}>{member.avatar}</span><span><strong>{member.name}</strong><small>{member.role} · Issue chest {member.chest}</small></span></button>)}{!memberSuggestions.length && <span className="suggestion-empty">No roster member found.</span>}</div>}</div><label>Role for this CTA<select value={role} onChange={(e) => setRole(e.target.value)}>{roleOptions.map((option) => <option key={option}>{option}</option>)}</select><small className="field-help">This can change from the member’s default role.</small></label><label>CTA event<input value={cta} onChange={(e) => setCta(e.target.value)} placeholder="e.g. Avalonian Roads" /></label><label>Issue from chest<input value={chest} onChange={(e) => setChest(e.target.value)} placeholder="Select a member to auto-fill" /></label><div className="field-full"><label>Replacement items</label><ItemAutocomplete items={items} selectedItems={selectedItems} setSelectedItems={setSelectedItems} onAddItem={onAddItem} /></div></div><div className="death-callout"><div className="death-pulse" /><div><strong>New open regear</strong><span>{selectedMember ? `${selectedMember.name} · ${role} · Chest ${chest || 'unassigned'}` : 'Search for the member who died'}{selectedItems.length ? ` · ${selectedItems.map((item) => item.name).join(', ')}` : ''}</span></div></div><div className="modal-footer"><button className="button button-ghost" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={!selectedMember} onClick={() => onSave({ memberName, role, note: `Died in ${cta} · just now`, chest: chest.trim() || 'Unassigned', items: selectedItems.map((item) => item.name) })}><Icon name="swords" size={15} />Create regear request</button></div></Modal> }
function ItemAutocomplete({ items, selectedItems, setSelectedItems, onAddItem }) { const [query, setQuery] = useState(''); const [open, setOpen] = useState(false); const suggestions = items.filter((item) => item.name.toLowerCase().includes(query.toLowerCase()) && !selectedItems.some((selected) => selected.name === item.name)).slice(0, 6); const choose = (item) => { setSelectedItems((current) => [...current, item]); setQuery(''); setOpen(false) }; const addNew = () => { const name = query.trim(); if (!name) return; const item = onAddItem(name); choose(item); }; return <div className="autocomplete"><div className="token-input">{selectedItems.map((item) => <button type="button" className="item-token" key={item.name} onClick={() => setSelectedItems((current) => current.filter((selected) => selected.name !== item.name))}>{item.name}<span>×</span></button>)}<input value={query} onFocus={() => setOpen(true)} onChange={(e) => { setQuery(e.target.value); setOpen(true) }} placeholder={selectedItems.length ? 'Add another item...' : 'Type an item name...'} /></div>{open && query.trim() && <div className="suggestion-box">{suggestions.map((item) => <button type="button" key={item.name} className="suggestion-row" onMouseDown={(e) => e.preventDefault()} onClick={() => choose(item)}><span className="suggestion-icon"><Icon name={item.category === 'Weapon' ? 'swords' : 'box'} size={14} /></span><span><strong>{item.name}</strong><small>{item.category} · stored item</small></span><Icon name="plus" size={14} /></button>)}{!suggestions.some((item) => item.name.toLowerCase() === query.trim().toLowerCase()) && <button type="button" className="suggestion-add" onMouseDown={(e) => e.preventDefault()} onClick={addNew}><Icon name="plus" size={14} />Add “{query.trim()}” to item catalog</button>}{!suggestions.length && <span className="suggestion-empty">No matching item. Add it to the catalog.</span>}</div>}</div> }
function ItemSlotPicker({ label, category, items, value, onChange, onAdd }) { const options = items.filter((item) => item.category === category || (category === 'Head' && item.category === 'Helmet')); const listId = `item-${category.toLowerCase().replace(/\s+/g, '-')}`; return <div className="slot-picker"><label>{label}<input list={listId} value={value} onChange={(event) => onChange(event.target.value)} placeholder={category === 'Off hand' ? 'Not applicable' : 'Type or search an item'} /></label><datalist id={listId}>{options.map((item) => <option key={item.id || `${item.name}-${item.tier}`} value={item.name}>{item.tier && item.tier !== 'Unspecified' ? `Tier ${item.tier}` : ''}</option>)}</datalist><button type="button" className="slot-add" onClick={() => onAdd(category)}>{options.length ? 'Missing an item?' : `No ${category.toLowerCase()} saved`} Add to catalog</button></div> }
function DeathModalDaily({ initialDate, members, items, onRequestAddItem, onClose, onSave }) { const today = dayKey(new Date()); const firstMember = members[0]; const [memberName, setMemberName] = useState(''); const [memberQuery, setMemberQuery] = useState(''); const [open, setOpen] = useState(false); const [role, setRole] = useState(firstMember?.role || 'DPS'); const [cta, setCta] = useState(''); const [diedDate, setDiedDate] = useState(initialDate || today); const [diedTime, setDiedTime] = useState(''); const [chest, setChest] = useState(''); const [weapon, setWeapon] = useState(''); const [offHand, setOffHand] = useState(''); const [helmet, setHelmet] = useState(''); const [armor, setArmor] = useState(''); const [boots, setBoots] = useState(''); const selectedMember = members.find((member) => member.name === memberName); const suggestions = members.filter((member) => `${member.name} ${member.role}`.toLowerCase().includes(memberQuery.toLowerCase())).slice(0, 7); const chooseMember = (member) => { setMemberName(member.name); setMemberQuery(member.name); setRole(member.role || 'DPS'); setChest(member.chest || 'Unassigned'); setOpen(false) }; const save = () => onSave({ memberId: selectedMember.id, memberName, role, cta, diedAt: new Date(`${diedDate}T${diedTime || '12:00'}:00`).toISOString(), chest: chest.trim() || 'Unassigned', note: cta ? `Died in ${cta}` : 'Death reported', items: [[weapon, 'Weapon'], [offHand, 'Off hand'], [helmet, 'Head'], [armor, 'Armor'], [boots, 'Boots']].filter(([name]) => name).map(([name, category]) => ({ name, category })) }); return <Modal title="Add daily regear" eyebrow="Record a member death" onClose={onClose}><div className="form-grid"><div className="member-search-field"><label>Member</label><div className="member-search"><Icon name="search" size={15} /><input autoFocus value={memberQuery} onFocus={() => setOpen(true)} onChange={(event) => { setMemberQuery(event.target.value); setMemberName(''); setOpen(true) }} placeholder="Search character name..." /></div>{open && memberQuery.trim() && <div className="member-suggestion-box">{suggestions.map((member) => <button type="button" key={member.id || member.name} onMouseDown={(event) => event.preventDefault()} onClick={() => chooseMember(member)}><span className={`avatar avatar-${member.tone}`}>{member.avatar}</span><span><strong>{member.name}</strong><small>{member.role} · Issue chest {member.chest}</small></span></button>)}{!suggestions.length && <span className="suggestion-empty">No roster member found.</span>}</div>}</div><label>Role for this death<select value={role} onChange={(event) => setRole(event.target.value)}>{roleOptions.map((option) => <option key={option}>{option}</option>)}</select></label><label>Death date<input type="date" value={diedDate} onChange={(event) => setDiedDate(event.target.value)} required /></label><label>Death time<input type="time" value={diedTime} onChange={(event) => setDiedTime(event.target.value)} /></label><label>CTA or location<input value={cta} onChange={(event) => setCta(event.target.value)} placeholder="Optional" /></label><label>Issue chest<input value={chest} onChange={(event) => setChest(event.target.value)} placeholder="Auto-filled from member" /></label><div className="field-full"><div className="slot-grid"><ItemSlotPicker label="Weapon" category="Weapon" items={items} value={weapon} onChange={setWeapon} onAdd={onRequestAddItem} /><ItemSlotPicker label="Off hand" category="Off hand" items={items} value={offHand} onChange={setOffHand} onAdd={onRequestAddItem} /><ItemSlotPicker label="Headgear" category="Head" items={items} value={helmet} onChange={setHelmet} onAdd={onRequestAddItem} /><ItemSlotPicker label="Armor" category="Armor" items={items} value={armor} onChange={setArmor} onAdd={onRequestAddItem} /><ItemSlotPicker label="Boots" category="Boots" items={items} value={boots} onChange={setBoots} onAdd={onRequestAddItem} /></div></div></div><div className="death-callout"><div className="death-pulse" /><div><strong>New open regear</strong><span>{selectedMember ? `${selectedMember.name} · ${role} · Chest ${chest || 'unassigned'}` : 'Search for the member who died'}</span></div></div><div className="modal-footer"><button type="button" className="button button-ghost" onClick={onClose}>Cancel</button><button type="button" className="button button-primary" disabled={!selectedMember} onClick={save}><Icon name="swords" size={15} />Add daily regear</button></div></Modal> }

function ItemModalLive({ onClose, onSave, initialCategory = 'Weapon' }) { const [name, setName] = useState(''); const [category, setCategory] = useState(initialCategory); const [tier, setTier] = useState('Unspecified'); const [quantity, setQuantity] = useState('0'); const [minimumQuantity, setMinimumQuantity] = useState('0'); const tiers = ['Unspecified', '1', '2', '3', '4', '4.1', '4.2', '4.3', '4.4', '5', '5.1', '5.2', '5.3', '5.4', '6', '6.1', '6.2', '6.3', '6.4', '7', '7.1', '7.2', '7.3', '7.4', '8', '8.1', '8.2', '8.3', '8.4']; return <Modal title="Add catalog item" eyebrow="Guild chest catalog" onClose={onClose}><div className="form-grid"><label>Item name<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Judicator Armor" /></label><label>Category<select value={category} onChange={(e) => setCategory(e.target.value)}><option>Weapon</option><option>Off hand</option><option>Head</option><option>Armor</option><option>Boots</option><option>Custom</option></select></label><label>Tier<select value={tier} onChange={(e) => setTier(e.target.value)}>{tiers.map((option) => <option key={option} value={option}>{option === 'Unspecified' ? option : `Tier ${option}`}</option>)}</select><small className="field-help">Albion tiers 4–8 support .1, .2, .3 and .4 variants.</small></label><label>Current quantity<input type="number" min="0" value={quantity} onChange={(e) => setQuantity(e.target.value)} inputMode="numeric" /></label><label>Minimum quantity<input type="number" min="0" value={minimumQuantity} onChange={(e) => setMinimumQuantity(e.target.value)} inputMode="numeric" /></label></div><div className="kit-callout"><Icon name="box" size={18} /><div><strong>Stored in the guild chest</strong><span>Chest locations are not assigned to catalog items. Members keep their own issue chest.</span></div></div><div className="modal-footer"><button className="button button-ghost" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={!name.trim()} onClick={() => onSave({ name: name.trim(), category, tier, quantity: Number(quantity) || 0, minimumQuantity: Number(minimumQuantity) || 0 })}><Icon name="plus" size={15} />Add item</button></div></Modal> }

function ItemModal({ onClose, onSave, initialCategory }) { return <ItemModalLive initialCategory={initialCategory} onClose={onClose} onSave={onSave} /> }
function PlanModal({ onClose, onSave }) { const [name, setName] = useState(''); const [budget, setBudget] = useState(''); const [date, setDate] = useState(''); const [time, setTime] = useState(''); const save = () => onSave({ name: name.trim(), budget, startsAt: new Date(`${date}T${time}:00`).toISOString() }); return <Modal title="Schedule CTA" eyebrow="CTA event" onClose={onClose}><div className="form-grid"><label>CTA name<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Avalonian Roads" /></label><label>Default kit template<select defaultValue="Caller standard"><option>Tank standard</option><option>Support standard</option><option>Healer standard</option><option>DPS standard</option><option>Bomb standard</option><option>Caller standard</option></select></label><label>Date<input type="date" value={date} onChange={(e) => setDate(e.target.value)} required /></label><label>Start time<input type="time" value={time} onChange={(e) => setTime(e.target.value)} required /></label><label>Attendees<select defaultValue="Select members"><option>Select members</option><option>All classified members</option><option>All active members</option></select></label><label>Silver budget<input value={budget} onChange={(e) => setBudget(e.target.value)} inputMode="numeric" placeholder="Optional" /></label></div><div className="kit-callout"><Icon name="swords" size={18} /><div><strong>Template for casualty requests</strong><span>When a death is reported, this template can fill replacement items for that role.</span></div></div><div className="modal-footer"><button className="button button-ghost" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={!name.trim() || !date || !time} onClick={save}>Schedule CTA</button></div></Modal> }

createRoot(document.getElementById('root')).render(<App />)
